 import { addMinutes } from 'date-fns';

+/**
+ * @description Gera os horários livres de um corretor num dia, em blocos de 30 min.
+ * @param inicio começo do expediente
+ * @param fim fim do expediente
+ * @param ocupados horários já tomados
+ */
+export function horariosLivres(inicio: Date, fim: Date, ocupados: Date[]): Date[] {
+  const livres: Date[] = [];
+  for (let t = inicio; t < fim; t = addMinutes(t, 30)) {
+    if (!ocupados.some((o) => o.getTime() === t.getTime())) livres.push(t);
+  }
+  return livres;
+}
+
 export const BLOCO_MINUTOS = 30;

